local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path;local b=require('_bootstrap');local a=b.lib('args');local o=a.parse(arg);local p=b.lib('process');local path=b.lib('path');local json=b.lib('json');local time=b.lib('time');local runtime=a.required(o,'runtime-exe');local renderer=a.required(o,'renderer-exe');local root=path.absolute(a.required(o,'evidence-dir'));local server=a.integer(a.required(o,'server-pid'),'server-pid',1);local r1=a.integer(a.required(o,'team1-runtime-pid'),'runtime',1);local r2=a.integer(a.required(o,'team2-runtime-pid'),'runtime',1);local f1=a.integer(a.required(o,'team1-renderer-pid'),'renderer',1);p.graceful_stop(f1,renderer,5000);time.sleep_ms(500);local events={{event='team-1-renderer-stopped',runtime_alive=p.inspect(r1)~=nil}};local start=p.run(b.lib('platform').lua_executable,{path.join(dir,'start_fog_demo_frontend.lua'),'--exe',renderer,'--cwd',path.join(b.root,'omfx'),'--pid-file',path.join(root,'team-1-renderer-restart.pid'),'--player-id','1','--team','1','--player-name','player1','--window-x','20','--presentation-addr','127.0.0.1:62001'},{cwd=b.root});local new=tonumber(start.stdout:match('(%d+)%s*$'));time.sleep_ms(2000);p.assert_identity(new,renderer);table.insert(events,{event='team-1-renderer-reconnected',renderer_pid=new,runtime_pid=r1});p.stop(r1,runtime);time.sleep_ms(500);table.insert(events,{event='team-1-runtime-stopped',server_alive=p.inspect(server)~=nil,team_2_runtime_alive=p.inspect(r2)~=nil});p.graceful_stop(new,renderer,3000);json.write(path.join(root,'lifecycle.json'),events,true)
